starttime() { local line rest f; read -r line < "/proc/$1/stat" || return 1; rest=${line##*) }; set -- $rest; echo "${20}"; }
mkq() { local tag=$1; shift; "$P/g1alpha" "${@:-60}" & PID[$tag]=$!; }
tied=no
for ((try=0;try<60;try++)); do
  mkq t1; mkq t2; mkq t3
  for t in t1 t2 t3; do wait_comm $t g1alpha; done
  a=$(starttime "${PID[t1]}"); b=$(starttime "${PID[t2]}"); c=$(starttime "${PID[t3]}")
  if [[ $a == "$b" && $b == "$c" ]]; then tied=yes; break; fi
  for t in t1 t2 t3; do kill -KILL "${PID[$t]}" 2>/dev/null; wait "${PID[$t]}" 2>/dev/null; done
done
echo "three-way-start-time-tie=$tied"
mk new g1alpha 70
# tie members are in ascending PID order only if the kernel handed them out that way
echo "pid-order-t1<t2<t3=$([[ ${PID[t1]} -lt ${PID[t2]} && ${PID[t2]} -lt ${PID[t3]} ]] && echo yes || echo no)"
